mapper.select:
SELECT A.SURVEY_SEQ, A.SURVEY_ID, A.SURVEY_TITLE, A.OPENED, A.CLOSED, A.ADMINEMAIL, A.BGCOLOR, A.TEXTCOLOR, A.REGISTER_NO, DATE_FORMAT(A.REGIST_DT, '%Y-%m-%d %H:%i') AS REGIST_DT, A.UPDUSR_NO, DATE_FORMAT(A.UPDT_DT, '%Y-%m-%d %H:%i') AS UPDT_DT FROM tb_survey A WHERE 1=1
AND ( A.SURVEY_TITLE LIKE CONCAT('%', #{searchKeyword}, '%') OR A.SURVEY_ID LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY A.REGIST_DT DESC LIMIT #{firstIndex}, #{recordCountPerPage}

SELECT A.SURVEY_SEQ, A.SURVEY_ID, A.SURVEY_TITLE, A.OPENED, A.CLOSED, A.ADMINEMAIL, A.ADMINPID, A.ACCESSRESULTSRESTRICTION, A.RESULTSPASSWORD, A.ENTRYRESTRICTION, A.ENTRYPASSWORD, A.MEMBERS, A.ONEENTRYONLY, A.SHOWBORDER, A.EXPORTDELIMITER, A.EXPORTINCLUDEQUESTIONS, A.IP, A.BROWSERID, A.BGCOLOR, A.TEXTCOLOR, A.FONT_SIZE, A.HEADER, A.FOOTER, A.BASEHREF, A.USERCSS, A.DIVIDER, A.EXITPAGETEXT_ISHTML, A.EXITPAGETEXT, A.NUMBERRODUCTIONTEXT, A.THEME_SEQ, A.LOGO_IMAGE_PATH, A.LOGO_ALIGN, A.SHOW_FOOTER_LOGO, A.LAYOUT_TYPE, A.FONT_FAMILY, A.ACCENT_COLOR, A.REGISTER_NO, DATE_FORMAT(A.REGIST_DT, '%Y-%m-%d %H:%i') AS REGIST_DT, A.UPDUSR_NO, DATE_FORMAT(A.UPDT_DT, '%Y-%m-%d %H:%i') AS UPDT_DT, B.BG_IMAGE_PATH AS bgImagePath FROM tb_survey A LEFT JOIN tb_survey_theme B ON A.THEME_SEQ = B.THEME_SEQ WHERE 1=1
AND A.SURVEY_SEQ = #{surveySeq}
AND A.SURVEY_ID = #{surveyId}

