SURVEY_TITLE = #{surveyTitle}, OPENED = #{opened}, CLOSED = #{closed}, ADMINEMAIL = #{adminEmail}, ADMINPID = #{adminPid}, ACCESSRESULTSRESTRICTION = #{accessResultsRestriction}, RESULTSPASSWORD = #{resultsPassword}, ENTRYRESTRICTION = #{entryRestriction}, ENTRYPASSWORD = #{entryPassword}, MEMBERS = #{members}, ONEENTRYONLY = #{oneEntryOnly}, SHOWBORDER = #{showBorder}, EXPORTDELIMITER = #{exportDelimiter}, EXPORTINCLUDEQUESTIONS = #{exportIncludeQuestions}, IP = #{ip}, BROWSERID = #{browserId}, BGCOLOR = #{bgColor}, TEXTCOLOR = #{textColor}, FONT_SIZE = #{fontSize}, HEADER = #{header}, FOOTER = #{footer}, BASEHREF = #{baseHref}, USERCSS = #{userCss}, DIVIDER = #{divider}, EXITPAGETEXT_ISHTML = #{exitPageTextIsHtml}, EXITPAGETEXT = #{exitPageText}, NUMBERRODUCTIONTEXT = #{numberRoductionText}, THEME_SEQ = #{themeSeq}, LOGO_IMAGE_PATH = #{logoImagePath}, LOGO_ALIGN = #{logoAlign}, SHOW_FOOTER_LOGO = #{showFooterLogo}, LAYOUT_TYPE = #{layoutType}, FONT_FAMILY = #{fontFamily}, ACCENT_COLOR = #{accentColor}, UPDUSR_NO = #{updusrNo}, UPDT_DT = NOW()
AND SURVEY_SEQ = #{surveySeq}
